import os, json

def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()

# Get demo 1
demo_in = G.get('Demo pair 1 input')
demo_out = G.get('Demo pair 1 output')
test_in = G.get('Test input')

print("Demo input shape:", len(demo_in), "x", len(demo_in[0]))
print("Demo output shape:", len(demo_out), "x", len(demo_out[0]))
print("Are shapes same?", len(demo_in)==len(demo_out))

# Check if the rule is: 6 -> 2 when on BOTH complete H and V lines of 6s
def solve(grid):
    if not grid or not grid[0]:
        return []
    h, w = len(grid), len(grid[0])

    # Find complete horizontal lines of 6s
    h_lines = set()
    for i in range(h):
        if all(grid[i][j] == 6 for j in range(w)):
            h_lines.add(i)

    # Find complete vertical lines of 6s
    v_lines = set()
    for j in range(w):
        if all(grid[i][j] == 6 for i in range(h)):
            v_lines.add(j)

    result = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 6 and i in h_lines and j in v_lines:
                result[i][j] = 2

    return result

# Test on demo input
result = solve(demo_in)

matches = True
for i in range(len(demo_out)):
    for j in range(len(demo_out[0])):
        if result[i][j] != demo_out[i][j]:
            matches = False
            print(f"Mismatch at ({i},{j}): got {result[i][j]}, expected {demo_out[i][j]}")
            break
    if not matches:
        break

print("\nAll match?", matches)

# Apply to test input
if matches:
    test_result = solve(test_in)
    print("\nTest result (first 5 rows):")
    for row in test_result[:5]:
        print(row)
    print("\nTest result JSON:")
    print(json.dumps(test_result))

